CREATE TABLE city(id BIGINT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE sport(id BIGINT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,color VARCHAR(30),icon VARCHAR(20));
CREATE TABLE park_category(id BIGINT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,color VARCHAR(30),icon VARCHAR(20));
CREATE TABLE tag(id BIGINT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE venue(id BIGINT PRIMARY KEY,sport_id BIGINT NOT NULL,city_id BIGINT NOT NULL,name VARCHAR(200) NOT NULL,sub_area VARCHAR(200),price_per_hour DECIMAL(10,2) NOT NULL,rating DECIMAL(3,2),FOREIGN KEY(sport_id) REFERENCES sport(id),FOREIGN KEY(city_id) REFERENCES city(id));
CREATE TABLE park(id BIGINT PRIMARY KEY,category_id BIGINT NOT NULL,city_id BIGINT NOT NULL,name VARCHAR(200) NOT NULL,area VARCHAR(250),base_price DECIMAL(10,2) NOT NULL,FOREIGN KEY(category_id) REFERENCES park_category(id),FOREIGN KEY(city_id) REFERENCES city(id));
CREATE TABLE stadium(id BIGINT PRIMARY KEY,sport_id BIGINT NOT NULL,city_id BIGINT NOT NULL,name VARCHAR(200) NOT NULL,area VARCHAR(250),base_price DECIMAL(10,2) NOT NULL,FOREIGN KEY(sport_id) REFERENCES sport(id),FOREIGN KEY(city_id) REFERENCES city(id));
CREATE TABLE stadium_event(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,stadium_id BIGINT NOT NULL,title VARCHAR(250) NOT NULL,starts_at TIMESTAMP NOT NULL,capacity INT,FOREIGN KEY(stadium_id) REFERENCES stadium(id));
CREATE TABLE stand_category(id BIGINT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,price_multiplier DECIMAL(5,2) NOT NULL);
CREATE TABLE coupon(id BIGINT PRIMARY KEY,code VARCHAR(50) NOT NULL UNIQUE,percent_off DECIMAL(5,2) NOT NULL,active BOOLEAN NOT NULL,valid_until TIMESTAMP);
CREATE TABLE venue_tag(venue_id BIGINT NOT NULL,tag_id BIGINT NOT NULL,PRIMARY KEY(venue_id,tag_id),FOREIGN KEY(venue_id) REFERENCES venue(id),FOREIGN KEY(tag_id) REFERENCES tag(id));
CREATE TABLE park_tag(park_id BIGINT NOT NULL,tag_id BIGINT NOT NULL,PRIMARY KEY(park_id,tag_id),FOREIGN KEY(park_id) REFERENCES park(id),FOREIGN KEY(tag_id) REFERENCES tag(id));
CREATE TABLE stadium_tag(stadium_id BIGINT NOT NULL,tag_id BIGINT NOT NULL,PRIMARY KEY(stadium_id,tag_id),FOREIGN KEY(stadium_id) REFERENCES stadium(id),FOREIGN KEY(tag_id) REFERENCES tag(id));
CREATE TABLE booking(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,status VARCHAR(20) NOT NULL,hold_expires_at TIMESTAMP,subtotal DECIMAL(12,2) NOT NULL,discount DECIMAL(12,2) NOT NULL,fee DECIMAL(12,2) NOT NULL,total DECIMAL(12,2) NOT NULL,split_count INT);
CREATE TABLE booking_item(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,booking_id BIGINT NOT NULL,item_type VARCHAR(20) NOT NULL,ref_id BIGINT NOT NULL,visit_date DATE,start_hour INT,event_id BIGINT,stand_id BIGINT,adults INT,children INT,family_passes INT,family_adults INT,family_children INT,picnic INT,price DECIMAL(12,2) NOT NULL,FOREIGN KEY(booking_id) REFERENCES booking(id));
CREATE TABLE slot_reservation(venue_id BIGINT NOT NULL,slot_date DATE NOT NULL,start_hour INT NOT NULL,booking_id BIGINT NOT NULL,PRIMARY KEY(venue_id,slot_date,start_hour),FOREIGN KEY(booking_id) REFERENCES booking(id));
CREATE INDEX idx_booking_hold ON booking(status,hold_expires_at);